// Candidate administration UI, entirely fictional and local to this Demo.
let adminQuery='',adminStatus='all',adminRoleFilter='all';
const adminRoutes=[['admin','管理概览','today'],['admin-users','用户账号','guide'],['admin-notices','公告','review'],['admin-site','站点设置','move'],['admin-audit','操作记录','date']];
function ensureAdminPreview(){
  state.preview.admin ||= {users:[
    {id:'user-lin',username:'xiaolin',role:'user',status:'active',created:'2026-10-11',lastLogin:'2026-10-16',emailVerified:true,version:1},
    {id:'user-friend',username:'preview_friend',role:'user',status:'active',created:'2026-10-16',lastLogin:'2026-10-16',emailVerified:true,version:1},
    {id:'user-early',username:'early_bird',role:'user',status:'active',created:'2026-10-12',lastLogin:'2026-10-14',emailVerified:false,version:1},
    {id:'user-weekend',username:'weekend_writer',role:'user',status:'disabled',created:'2026-10-05',lastLogin:'2026-10-08',emailVerified:true,version:1},
    {id:'admin-current',username:'lifexp_admin',role:'admin',status:'active',created:'2026-10-10',lastLogin:'2026-10-16',emailVerified:true,version:1}
  ],audit:[],site:{name:'LifeXP',support:'有问题先保留原文，稍后再处理。',defaultAIEnabled:false,dailyQuota:5}};
  return state.preview.admin;
}
function adminStats(){const users=ensureAdminPreview().users,normal=users.filter(user=>user.role==='user');return {total:normal.length,active:normal.filter(user=>user.status==='active').length,disabled:normal.filter(user=>user.status==='disabled').length,administrators:users.filter(user=>user.role==='admin').length,today:normal.filter(user=>user.created==='2026-10-16').length,recent:normal.filter(user=>user.lastLogin&&user.lastLogin>='2026-10-10').length};}
function adminDenied(){return heading('管理入口','日常账号不显示管理功能。')+`<section class="card"><p class="dashboard-quote">这里是独立管理工作区。查看候选界面，请在审阅页切换管理体验身份。</p><button class="btn" data-nav="preview">切换体验身份</button></section>`;}
function adminHeader(title,subtitle){return `<div class="page-header-action">${heading(title,subtitle,'LifeXP · 管理工作区')}${currentPage==='admin-account'?'':'<button class="btn small-btn" style="margin-top:16px" data-nav="admin-account">管理账号</button>'}</div>`+candidateNote('全部人数、账号和操作都是虚构样例，不代表云端真实统计。管理范围待你确认。');}
function adminPage(){
  if(state.preview.role!=='admin')return adminDenied();
  const stats=adminStats(),audit=ensureAdminPreview().audit;
  return adminHeader('管理概览','先看站点规模与状态，再处理需要关注的事项。')+`<div class="suite-grid three admin-stats">${[['用户账号',stats.total,'不含管理账号'],['正常用户',stats.active,'可以正常使用的示例账号'],['已停用用户',stats.disabled,'保留数据，不做删除'],['今日新增',stats.today,'示例统计日：2026-10-16'],['近 7 日登录',stats.recent,'按账号去重的示例人数'],['管理账号',stats.administrators,'与日常使用账号分开']].map(([label,count,note])=>`<section class="card"><p class="stat-label">${label}</p><strong class="stat-number">${count}</strong><p class="subtle-note">${note}</p></section>`).join('')}</div><div class="suite-grid" style="margin-top:20px"><section class="card"><h2>常用管理操作</h2><button class="menu-row" data-nav="admin-users"><div><strong>用户账号</strong><span class="muted">查找账号、查看状态、停用与恢复</span></div><span>→</span></button><button class="menu-row" data-nav="admin-notices"><div><strong>公告</strong><span class="muted">编辑、预览、发布与撤下</span></div><span>→</span></button><button class="menu-row" data-nav="admin-site"><div><strong>站点设置</strong><span class="muted">注册开关、站点说明与默认 AI 候选</span></div><span>→</span></button></section><section class="card"><div class="section-head"><h2>最近管理操作</h2><button class="link-btn" data-nav="admin-audit">查看全部 →</button></div>${audit.length?audit.slice(-3).reverse().map(adminAuditRow).join(''):'<p class="suite-empty">还没有管理操作。可以先查看用户账号或预览公告。</p>'}<div class="review-divider"></div><p class="small muted">运营统计不展示用户日记、AI 对话、密码或密钥。</p></section></div>`;
}
function adminUsersPage(){
  if(state.preview.role!=='admin')return adminDenied();
  const users=ensureAdminPreview().users.filter(user=>(!adminQuery||user.username.toLowerCase().includes(adminQuery.toLowerCase()))&&(adminStatus==='all'||user.status===adminStatus)&&(adminRoleFilter==='all'||user.role===adminRoleFilter));
  return adminHeader('用户账号','人数与账号状态放在这里，个人记录仍属于用户。')+`<section class="card"><div class="admin-filters"><label>查找账号<input id="admin-search" value="${esc(adminQuery)}" placeholder="输入用户名"></label><label>状态<select id="admin-status"><option value="all">所有状态</option><option value="active" ${adminStatus==='active'?'selected':''}>正常</option><option value="disabled" ${adminStatus==='disabled'?'selected':''}>已停用</option></select></label><label>身份<select id="admin-role-filter"><option value="all">所有身份</option><option value="user" ${adminRoleFilter==='user'?'selected':''}>普通用户</option><option value="admin" ${adminRoleFilter==='admin'?'selected':''}>管理员</option></select></label><button class="btn" data-suite="admin-search">查找</button></div><div class="section-head"><h2>账号列表 <span class="count">${users.length} 个匹配</span></h2><span class="small muted">总用户 ${adminStats().total} · 管理账号 ${adminStats().administrators}</span></div><table class="admin-users-table"><caption class="visually-hidden">虚构示例账号及状态</caption><thead><tr><th>账号</th><th>身份 / 邮箱验证</th><th>状态</th><th>注册日期</th><th>最近登录</th><th>操作</th></tr></thead><tbody>${users.map(user=>`<tr data-user-id="${user.id}"><td data-label="账号"><strong>${esc(user.username)}</strong>${user.id==='admin-current'?'<span class="small muted" style="display:block">当前管理账号</span>':''}</td><td data-label="身份">${user.role==='admin'?'管理员':'普通用户'}<small>${user.emailVerified?'邮箱已验证':'邮箱待验证'}</small></td><td data-label="状态"><span class="badge ${user.status==='active'?'green':'amber'}">${user.status==='active'?'正常':'已停用'}</span></td><td data-label="注册">${user.created}</td><td data-label="最近登录">${user.lastLogin||'尚未登录'}</td><td data-label="操作">${user.role==='admin'?'<span class="small muted">管理账号不在此停用</span>':`<button class="btn small-btn" data-manage-user="${user.id}">${user.status==='active'?'停用':'恢复'}</button>`}</td></tr>`).join('')||'<tr><td colspan="6"><p class="suite-empty">没有匹配账号，换个条件试试。</p></td></tr>'}</tbody></table><p class="subtle-note">停用只改变账号状态并保留数据；是否加入实际会话撤销、通知及申诉流程，开发前再确认。本版不提供删库、改余额或浏览私人内容。</p></section>`;
}
function adminNoticesPage(){
  if(state.preview.role!=='admin')return adminDenied();const notice=state.preview.notice;
  return adminHeader('公告管理','先预览，再发布到用户首页；需要时可以撤下。')+`<div class="suite-grid"><section class="card"><div class="section-head"><h2>编辑公告</h2><span class="badge ${notice.published?'green':'gray'}">${notice.published?'示例已发布':'未发布'}</span></div><div class="form-grid"><label>标题<input id="notice-title" value="${esc(notice.title)}" maxlength="100"></label><label>公告内容<textarea id="notice-body" maxlength="2000">${esc(notice.body)}</textarea></label><div class="row wrap"><button class="btn" data-suite="preview-notice">预览</button><button class="btn primary" data-suite="publish-notice">发布到本机示例</button><button class="btn quiet" data-suite="withdraw-notice">撤下</button></div></div></section><section class="card"><h2>发布状态</h2><p class="dashboard-quote">${notice.published?'普通账号首页会显示这条本机公告，用户可以收起。':'普通账号首页不再显示这条公告。'}</p><p class="small muted">编辑文本不会立即改变首页，发布和撤下会留下管理操作记录。</p></section></div>`;
}
function adminSitePage(){
  if(state.preview.role!=='admin')return adminDenied();const site=ensureAdminPreview().site;
  return adminHeader('站点设置','保留第一阶段用得上的设置，复杂运营能力以后再加。')+`<div class="suite-grid"><section class="card"><h2>站点与注册</h2><div class="info-line"><div><strong>开放注册</strong><p class="small muted">普通注册不要求邀请码</p></div><button class="toggle" data-suite="toggle-registration" role="switch" aria-checked="${state.preview.registrationOpen}" aria-label="开放注册"></button></div><div class="form-grid"><label>站点名称<input id="admin-site-name" maxlength="50" value="${esc(site.name)}"></label><label>用户帮助说明<textarea id="admin-support" maxlength="500">${esc(site.support)}</textarea></label></div></section><section class="card"><div class="section-head"><h2>站点默认 AI</h2><span class="candidate">启用及额度待确认</span></div><p class="small muted">站点凭据独立配置，不读取普通用户的模型密钥。这里没有真实 Key。</p><div class="form-grid"><label class="checkbox-label"><input id="admin-ai-enabled" type="checkbox" ${site.defaultAIEnabled?'checked':''}>启用站点默认 AI · 本机候选开关</label><label>每人每日调用额度 · 示例<input id="admin-ai-quota" type="number" min="1" max="1000" step="1" value="${site.dailyQuota}"></label><p class="input-help">额度与运营预算尚未选定。这个数字不控制真实调用，也不自动改变普通账号的 AI 选择。</p></div><p class="subtle-note">服务状态、调用量及预算监控建议随真实默认 AI 接入一并增加；本版不编造实时监控数值。</p></section></div><section class="card" style="margin-top:20px"><div class="row between wrap"><p class="small muted">本机候选设置独立保存，不修改用户原文、金币或真实服务器。</p><button class="btn primary" data-suite="admin-save-site">保存候选设置</button></div><div id="admin-site-error" class="error-box" role="alert" hidden></div><div id="admin-site-success" class="success-box" role="status" hidden></div></section>`;
}
function adminAuditRow(row){return `<article class="admin-audit-row"><div class="row between wrap"><strong>${esc(row.action)}</strong><span class="small muted">${esc(new Date(row.time).toLocaleString('zh-CN'))}</span></div><p>${esc(row.target)} · ${esc(row.summary)}</p><p class="small muted">操作者：${esc(row.actor)}</p></article>`;}
function adminAuditPage(){if(state.preview.role!=='admin')return adminDenied();const audit=ensureAdminPreview().audit;return adminHeader('管理操作记录','谁在什么时候做了什么，方便之后查清楚。')+`<section class="card"><div class="section-head"><h2>已记录操作 <span class="count">${audit.length} 条</span></h2><span class="badge gray">本机示例</span></div>${audit.length?[...audit].reverse().map(adminAuditRow).join(''):'<p class="suite-empty">还没有管理操作。发布公告、停用/恢复账号、改变注册开关或保存站点设置后，会留下记录。</p>'}<p class="subtle-note">这里记录管理操作，不展示用户日记、AI 对话、密码或 Key。</p></section>`;}
function adminAccountPage(){if(state.preview.role!=='admin')return adminDenied();return `<button class="link-btn page-back" data-admin-back data-nav="${esc(adminAccountOrigin||'admin')}"><span aria-hidden="true">←</span> 返回上一页</button>`+adminHeader('管理账号安全','管理身份的设置单独放置，不混入普通账号的个人页面。')+`<section class="card"><div class="info-line"><span>当前管理账号</span><strong>lifexp_admin</strong></div><div class="info-line"><span>身份</span><span class="badge amber">管理员 · 示例</span></div><div class="record-actions"><button class="btn" data-suite="change-password">体验管理员改密</button><button class="btn quiet" data-role="user">退出管理体验</button></div><p class="subtle-note">这里仅切换本机预览身份；正式登录、改密和会话退出仍须由服务端处理。</p></section>`;}
function addAdminAudit(action,target,summary){ensureAdminPreview().audit.push({id:crypto.randomUUID(),time:new Date().toISOString(),actor:'lifexp_admin',action,target,summary});}
function openUserStatus(id){
  if(state.preview.role!=='admin')return;const user=ensureAdminPreview().users.find(user=>user.id===id);if(!user||user.role==='admin')return;
  const version=user.version,next=user.status==='active'?'disabled':'active',label=next==='disabled'?'停用':'恢复';
  showPreviewDialog(label+'这个账号？',`<h3 style="margin-top:16px">${esc(user.username)}</h3><p class="dashboard-quote">${next==='disabled'?'暂停这个示例账号的使用状态，个人数据仍保留。':'把这个示例账号恢复为正常状态。'}</p><div class="form-grid"><label>操作原因<textarea id="admin-user-reason" maxlength="300" placeholder="写一句，方便之后回看。"></textarea></label></div>`,()=>{
    if(state.preview.role!=='admin'||user.version!==version)return;const reason=document.getElementById('admin-user-reason')?.value.trim();if(!reason){modalError('请填写本次操作原因。');return;}
    user.status=next;user.version++;addAdminAudit(label+'账号',user.username,reason);persist();closePreviewDialog();render();
  },'确认'+label);
}
function handleSettingsAction(action){
  if(action==='admin-search'){if(state.preview.role!=='admin')return;adminQuery=document.getElementById('admin-search').value.trim();adminStatus=document.getElementById('admin-status').value;adminRoleFilter=document.getElementById('admin-role-filter').value;render();return;}
  if(action==='admin-save-site'){
    if(state.preview.role!=='admin')return;const name=document.getElementById('admin-site-name').value.trim(),support=document.getElementById('admin-support').value.trim(),quota=Number(document.getElementById('admin-ai-quota').value),enabled=document.getElementById('admin-ai-enabled').checked;
    if(!name||!Number.isInteger(quota)||quota<1||quota>1000){const error=document.getElementById('admin-site-error');error.textContent='请填写站点名称及 1～1000 的整数示例额度。';error.hidden=false;return;}
    const next={name,support,defaultAIEnabled:enabled,dailyQuota:quota},admin=ensureAdminPreview();if(JSON.stringify(admin.site)!==JSON.stringify(next)){admin.site=next;addAdminAudit('保存站点设置',name,'更新站点说明及默认 AI 候选设置');persist();}render();const message=document.getElementById('admin-site-success');message.textContent='候选设置已保存到本机示例。';message.hidden=false;return;
  }
  if(['publish-notice','withdraw-notice','toggle-registration','pause-account'].includes(action)){
    if(state.preview.role!=='admin')return;ensureAdminPreview();const before=JSON.stringify({notice:state.preview.notice,registration:state.preview.registrationOpen,paused:state.preview.accountPaused});
    routineHandleSettingsAction(action);
    const after=JSON.stringify({notice:state.preview.notice,registration:state.preview.registrationOpen,paused:state.preview.accountPaused});
    if(before!==after){const labels={'publish-notice':'发布公告','withdraw-notice':'撤下公告','toggle-registration':'改变注册开关','pause-account':'改变旧版示例账号状态'};addAdminAudit(labels[action],action.includes('notice')?state.preview.notice.title:'站点',action==='toggle-registration'?(state.preview.registrationOpen?'开放注册':'关闭注册'):'仅更新本机候选状态');persist();render();}return;
  }
  routineHandleSettingsAction(action);
}
function previewDirectory(){return state.preview.role==='admin'?[['admin','看管理概览','人数、状态与最近操作'],['admin-users','查看用户账号','查找、状态、注册与登录日期'],['admin-notices','试公告管理','预览、发布与撤下'],['admin-site','看站点设置','注册与默认 AI 候选'],['admin-audit','查看操作记录','管理动作及原因']]:[['today','记一件事','保存 → 分析 → 确认'],['review','写晚间日记','原文与问答分区'],['plans','试计划打卡','周几、间隔、三种结果'],['growth','看成长和商店','独立天数、成就与兑换'],['settings','试模型配置','错误模型、测试与摘要'],['export','下载示例存档','可选原文和完整问答'],['auth','体验注册找回','仅模拟，不发邮件'],['admin','查看管理候选','先切换管理体验身份']];}
document.addEventListener('click',event=>{const button=event.target.closest('button');if(!button?.dataset.manageUser)return;event.stopImmediatePropagation();openUserStatus(button.dataset.manageUser);},true);
